#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader backdrop;
float4 amzSample_comp(float2 uv) { return float4(backdrop.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_comp(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_aSpeed;
uniform float amzp_progress;
uniform float amzp_motion;
uniform float amzp_amount;
uniform float amzp_dolly;
uniform float amzp_moveX;
uniform float amzp_moveY;
uniform float amzp_focus;
uniform float amzp_quality;
uniform float amzp_depthSrc;
uniform float amzp_invertDepth;
uniform float amzp_depthSmooth;
uniform float amzp_showDepth;
uniform float amzp_overdrawOn;
    float2 SS;
    float PXS;
    void dpInit() { SS = max(screen.zw, float2(1.0)); PXS = screen.zw.x / max(screen.zw.x, 1.0); }
    float4 colRaw(float2 uv) { uv = clamp(uv, float2(0.0), float2(1.0)); return int(amzp_depthSrc) == 0 ? amzTexture(1, uv) : amzTexture(0, uv); }
    float depRaw(float2 uv) {
        uv = clamp(uv, float2(0.0), float2(1.0));
        float4 c = int(amzp_depthSrc) == 0 ? amzTexture(0, uv) : amzTexture(1, uv);
        float3 u = c.a > 0.0001 ? c.rgb / c.a : float3(0.0);
        float d = dot(u, float3(0.299, 0.587, 0.114));
        return (amzp_invertDepth>0.5) ? 1.0 - d : d;
    }
    float dep(float2 uv) {
        float r = amzp_depthSmooth * PXS;
        if (r < 0.5) return depRaw(uv);
        float2 o = r / SS;
        float s = depRaw(uv) * 2.0;
        s += depRaw(uv + float2(o.x, 0.0)) + depRaw(uv - float2(o.x, 0.0)) + depRaw(uv + float2(0.0, o.y)) + depRaw(uv - float2(0.0, o.y));
        s += 0.7 * (depRaw(uv + o) + depRaw(uv - o) + depRaw(uv + float2(o.x, -o.y)) + depRaw(uv + float2(-o.x, o.y)));
        return s / 8.8;
    }
    float lum(float3 c) { return dot(c, float3(0.299, 0.587, 0.114)); }
    void nmFxMain() {
        float2 p = amzScreenNorm();
        float t = (amzp_autop>0.5) ? amzp_progress + time * amzp_aSpeed : amzp_progress;
        float a = 6.2831853 * t;
        float2 o = float2(0.0);
        float z = 0.0;
        if (int(amzp_motion) == 0) { o = float2(amzp_moveX, -amzp_moveY); z = amzp_dolly; }
        else if (int(amzp_motion) == 1) o = float2(cos(a), sin(a));
        else if (int(amzp_motion) == 2) o = float2(sin(a), 0.0);
        else if (int(amzp_motion) == 3) o = float2(0.0, sin(a));
        else if (int(amzp_motion) == 4) z = amzp_dolly * (0.5 - 0.5 * cos(a)) * 2.0;
        else { o = float2(cos(a), sin(a)) * 0.7; z = amzp_dolly * sin(a); }
        if (int(amzp_motion) != 0 && int(amzp_motion) != 4 && int(amzp_motion) != 5) z = 0.0;
        o *= amzp_amount * PXS / SS;
        float2 c = float2(0.5);
        float N = amzp_quality < 1.5 ? 16.0 : (amzp_quality < 2.5 ? 24.0 : (amzp_quality < 3.5 ? 32.0 : (amzp_quality < 4.5 ? 48.0 : 64.0)));
        float hPrev = 1.0;
        float hHit = 0.0;
        float2 sHit = p;
        bool found = false;
        for (int i = 0; i <= 64; i++) {
            float fi = float(i);
            if (fi > N) break;
            float h = 1.0 - fi / N;
            float k = z * (h - amzp_focus);
            float2 s = (p - o * (h - amzp_focus) + c * k) / (1.0 + k);
            float d = dep(s);
            if (d >= h) {
                float lo = h, hi = hPrev;
                for (int j = 0; j < 5; j++) {
                    float m = 0.5 * (lo + hi);
                    float km = z * (m - amzp_focus);
                    float2 sm = (p - o * (m - amzp_focus) + c * km) / (1.0 + km);
                    if (dep(sm) >= m) lo = m; else hi = m;
                }
                hHit = lo;
                float kh = z * (hHit - amzp_focus);
                sHit = (p - o * (hHit - amzp_focus) + c * kh) / (1.0 + kh);
                found = true;
                break;
            }
            hPrev = h;
        }
        if (!found) { float k0 = z * (0.0 - amzp_focus); sHit = (p - o * (0.0 - amzp_focus) + c * k0) / (1.0 + k0); }
        amzOutput = colRaw(sHit);
    }
    void amzRender() {
        dpInit();
        if ((amzp_showDepth>0.5)) { float d = dep(amzScreenNorm()); amzOutput = float4(float3(d), 1.0); }
        else nmFxMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
